package dev.benyamin.kumiho.ui.diagnostics

import dev.benyamin.kumiho.diagnostics.AndroidFacts
import dev.benyamin.kumiho.engine.DoctorCheck
import dev.benyamin.kumiho.engine.DoctorReport
import dev.benyamin.kumiho.engine.DoctorStatus

/** Copy generated by the diagnostics state machine, resolved by the screen. */
enum class DiagnosticsMessage {
    RESET_DONE,
    RESET_FAILED,
    LOAD_FAILED,
    COPIED,
}

/** Everything the Diagnostics screen renders. */
data class DiagnosticsUiState(
    val loading: Boolean = true,
    val report: DoctorReport? = null,
    val facts: AndroidFacts? = null,
    val error: String? = null,
    val resetting: Boolean = false,
    val resetDialog: Boolean = false,
    val message: DiagnosticsMessage? = null,
) {
    /** True once a report exists, so a re-run can keep it on screen. */
    val hasReport: Boolean get() = report != null

    /** The checks the Android app should show; desktop-only ones are dropped. */
    val checks: List<DoctorCheck> get() = DiagnosticsReducer.visibleChecks(report)
}

/**
 * Pure presentation and filtering helpers for the doctor report.
 *
 * The Go facade already drops Linux plumbing for Android, but the client keeps
 * its own deny-list: a report from a desktop build (or a future Go change) must
 * never show checks this app cannot act on. Everything here is JVM-testable.
 */
object DiagnosticsReducer {
    /**
     * Checks that only make sense on a desktop host. They are removed, not
     * rendered as skips: an Android user has no `nftables`, systemd or service
     * manager to fix.
     */
    val DESKTOP_ONLY_CHECKS: Set<String> = setOf(
        "platform",
        "tun-device",
        "cap-net-admin",
        "nftables",
        "systemd-resolved",
        "dns-manager",
        "tailscale",
        "ipv6",
        "default-route",
        "socks-port",
        "control-socket",
        "control-pipe",
        "windows-service",
        "tun-adapter",
        "adapter-dns",
        "physical-default-route",
        "elevation",
    )

    /** The report's checks minus the desktop-only plumbing. Order is kept. */
    fun visibleChecks(report: DoctorReport?): List<DoctorCheck> =
        report?.checks.orEmpty().filter { it.name !in DESKTOP_ONLY_CHECKS }

    /** The report's checks minus the desktop-only plumbing. */
    fun visibleChecks(checks: List<DoctorCheck>): List<DoctorCheck> =
        checks.filter { it.name !in DESKTOP_ONLY_CHECKS }

    /** The visible thresholds shown in the report header. */
    fun statusCounts(checks: List<DoctorCheck>): Map<DoctorStatus, Int> =
        checks.groupingBy { it.status }.eachCount()

    /** A check by its wire name, or null when the report lacks it. */
    fun check(report: DoctorReport?, name: String): DoctorCheck? =
        report?.checks?.firstOrNull { it.name == name }

    /**
     * The "Copy all" text: a plain-text report of the facts and every visible
     * check. It contains no tokens and nothing the engine did not already
     * report; traces and secrets are not read.
     */
    fun reportText(report: DoctorReport?, facts: AndroidFacts?): String {
        if (report == null) return ""
        val builder = StringBuilder()
        builder.appendLine("Kumiho diagnostics")
        builder.appendLine("version: ${report.version}")
        builder.appendLine("host: ${report.host}")
        builder.appendLine("os: ${report.os}")
        builder.appendLine("time: ${report.time}")
        builder.appendLine("failed: ${report.failed}")
        builder.appendLine("warned: ${report.warned}")
        builder.appendLine("skipped: ${report.skipped}")
        if (facts != null) {
            builder.appendLine()
            builder.appendLine("Android facts")
            builder.appendLine("device: ${facts.device}")
            builder.appendLine("sdk: ${facts.sdk}")
            builder.appendLine("vpn_permission: ${facts.vpnPermission}")
            builder.appendLine("always_on: ${facts.alwaysOn}")
            builder.appendLine("lockdown: ${facts.lockdown}")
            builder.appendLine("notifications: ${facts.notifications}")
            builder.appendLine("battery_optimized: ${facts.batteryOptimized}")
            builder.appendLine("network: ${facts.network}")
            builder.appendLine("dns_servers: ${facts.dnsServers.joinToString(",")}")
            builder.appendLine("private_dns_mode: ${facts.privateDnsMode}")
            builder.appendLine("socks_port_listening: ${facts.socksPortListening}")
            builder.appendLine("http_proxy_port_listening: ${facts.httpProxyPortListening}")
            builder.appendLine("service_running: ${facts.serviceRunning}")
            builder.appendLine("engine_state: ${facts.engineState}")
        }
        val checks = visibleChecks(report)
        if (checks.isNotEmpty()) {
            builder.appendLine()
            builder.appendLine("Checks")
            checks.forEach { check ->
                builder.append("- [${check.status.wire}] ${check.name}: ${check.detail}")
                if (!check.remediation.isNullOrBlank()) {
                    builder.append(" — ${check.remediation}")
                }
                builder.appendLine()
            }
        }
        return builder.toString()
    }

    /** A stable one-line summary of the report's visible checks. */
    fun summary(report: DoctorReport?, checks: List<DoctorCheck> = visibleChecks(report)): String {
        if (report == null) return ""
        val counts = statusCounts(checks)
        val failed = counts[DoctorStatus.FAIL] ?: 0
        val warned = counts[DoctorStatus.WARN] ?: 0
        val skipped = counts[DoctorStatus.SKIP] ?: 0
        return "$failed failed · $warned warnings · $skipped skipped"
    }
}
